#!/usr/bin/env python3
"""Independent school salary extraction from PDFMiner positioned original characters."""
import json,hashlib,re,unicodedata
from pathlib import Path
from pdfminer.high_level import extract_pages
from pdfminer.layout import LTChar,LTAnno
BASE=Path('research/salaries/queue-completion-2026-11-01/reviews')
SOURCES=[dict(id='sd27',slug='school-district-27',pdf='/tmp/continuation-schools/district-sd27-bb4215a005b0.pdf',sha='bb4215a005b063956cbb5cca9d6da73379dad5d470e6a0346f3eebcfe3a9fe61',pages=list(range(55,61)),cols=[0,250,340,430,520],trusteePage=55,trusteeMinY=560,employeeMaxY=500),dict(id='sd22',slug='school-district-22',pdf='/tmp/pofbc-schools/ministry-sd22-2025.pdf',sha='4657c26f966659bc5bf0de5a6e65818538f588dcbc154d7b23748b7cfe5415a6',pages=list(range(54,72)),cols=[0,201,381,481,570],trusteePage=54,trusteeMinY=370,employeeMaxY=330),dict(id='sd44',slug='school-district-44',pdf='/tmp/pofbc-schools/ministry-sd44-2025.pdf',sha='24312eed671fe2077c259aa534451dfd881cef89d14bac02eadc801f07a08b42',pages=list(range(51,69)),cols=[0,225,420,498,570],trusteePage=51,trusteeMinY=580,employeeMaxY=550)]
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
def chars(obj):
 if isinstance(obj,LTChar):yield obj
 elif hasattr(obj,'__iter__'):
  for child in obj:yield from chars(child)
def norm(text):return re.sub(r'\s+',' ',unicodedata.normalize('NFKC',text)).strip()
def text(items):
 items=sorted(items,key=lambda c:c.x0);s='';last=None
 for c in items:
  if last and c.x0-last.x1>max(1.7,c.size*.21):s+=' '
  s+=c.get_text();last=c
 return norm(s)
def amount(s):
 s=s.replace('$','').replace(',','').replace(' ','')
 if s in ['','-','–','—']:return None
 if not re.fullmatch(r'\d+(?:\.\d+)?',s):raise ValueError(f'Invalid money {s!r}')
 return float(s) if '.' in s else int(s)
for config in SOURCES:
 assert sha(config['pdf'])==config['sha']
 rows=[];geometry=[];allLines=[]
 for pno,layout in zip(config['pages'],extract_pages(config['pdf'],page_numbers=[x-1 for x in config['pages']])):
  buckets=[]
  for c in chars(layout):
   # Baselines are grouped by original PDF y0, independent of content text order.
   y=c.y0;bucket=next((b for b in buckets if abs(b['y']-y)<2.6),None)
   if bucket is None:bucket={'y':y,'chars':[]};buckets.append(bucket)
   bucket['chars'].append(c)
  lines=[]
  for b in sorted(buckets,key=lambda z:-z['y']):
   cols=[]
   for lo,hi in zip(config['cols'],config['cols'][1:]):cols.append(text([c for c in b['chars'] if lo<=c.x0<hi]))
   if any(cols):lines.append(dict(y=round(b['y'],3),columns=cols))
  allLines.append(dict(physicalPage=pno,lines=lines))
  anchors=[]
  for j,line in enumerate(lines):
   name,position,pay,expense=line['columns']
   # A person row has a source name and numeric remuneration. Controls are retained separately.
   if not re.fullmatch(r'\$?\s*\d[\d,]*(?:\.\d+)?',pay):continue
   if not name or re.match(r'^(?:total\b|subtotal\b|consolidated\b|employees earning\b|remuneration\b|schedule\b|name$|under \$|\$75,000 or less)',name.lower()):continue
   if config['id']=='sd27' and pno==60:
    boundary=next(l['y'] for l in lines if l['columns'][0].startswith('TOTAL FOR EMPLOYEES'))
    if line['y']<=boundary:continue
   if pno==config['trusteePage']:
    if line['y']>=config['trusteeMinY']:cohort='trustees'
    elif line['y']<config['employeeMaxY']:cohort='employees'
    else:continue
   else:cohort='employees'
   anchors.append((j,line,cohort))
  for idx,(j,line,cohort) in enumerate(anchors):
   name,position,pay,expense=line['columns']
   # Position-only continuation lines after this named amount row and before the next.
   nexty=anchors[idx+1][1]['y'] if idx+1<len(anchors) else 0
   continuations=[]
   if position:
    for l in lines[j+1:]:
     if l['y']<=nexty+2.6:break
     a,b,c,d=l['columns']
     if not a and b and not c and not d:continuations.append(b)
   title=' '.join([position,*continuations]).strip() or None
   if config['id']=='sd27' and cohort=='employees':title=None
   record=[config['slug'],name,title,amount(pay),amount(expense),pno]
   rows.append(dict(cohort=cohort,row=record));geometry.append(dict(cohort=cohort,physicalPage=pno,y=line['y'],sourceName=name,sourcePayLiteral=pay,sourceExpensesLiteral=expense,positionContinuations=continuations))
  print(config['id'],pno,'person anchors',len(anchors))
 out=dict(reviewedOn='2026-11-01',reviewer='/root/recovery_review',method='independent PDFMiner20251230 LTChar baseline and geometric column extraction',sourcePath=config['pdf'],sourceSha256=config['sha'],physicalSalaryPages=config['pages'],candidatePayloadOpenedBeforeFreeze=False,rows=rows,rowGeometry=geometry,allSalaryPageColumnLines=allLines,readerCode=Path(__file__).read_text(),acceptedEmployeeRows=0)
 dest=BASE/f"independent-school-queue-{config['id']}-pdfminer-original-extraction-v2.json"
 with dest.open('x') as f:json.dump(out,f,ensure_ascii=False,indent=2);f.write('\n')
 print(json.dumps({'file':str(dest),'sha256':sha(dest),'rows':len(rows),'trustees':sum(x['cohort']=='trustees' for x in rows),'employees':sum(x['cohort']=='employees' for x in rows)}))
